import{_ as t}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as a,c as r,ak as i}from"./chunks/framework.DC-k2h36.js";const s="/projects/esp32Sensor/en/latest/assets/1.DAXx06Rz.webp",n="/projects/esp32Sensor/en/latest/assets/2.C246uvoj.webp",l="/projects/esp32Sensor/en/latest/assets/3.kyLSK1fO.webp",d="/projects/esp32Sensor/en/latest/assets/4.CbYuEgp3.webp",c="/projects/esp32Sensor/en/latest/assets/5.DsUC_Jyi.webp",x=JSON.parse('{"title":"13. Soil Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/13. Soil Sensor.md","filePath":"docs/13. Soil Sensor.md"}'),h={name:"docs/13. Soil Sensor.md"};function p(m,e,g,u,_,b){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="_13-soil-sensor" tabindex="-1">13. Soil Sensor <a class="header-anchor" href="#_13-soil-sensor" aria-label="Permalink to &quot;13. Soil Sensor&quot;">​</a></h1><h2 id="_13-1-introduction" tabindex="-1">13.1 Introduction <a class="header-anchor" href="#_13-1-introduction" aria-label="Permalink to &quot;13.1 Introduction&quot;">​</a></h2><p>The soil sensor detects moisture in the ground and converts it into analog signal outputs. Pairing this sensor with a water pump module and tubing makes it easy to build an automatic plant-watering system that waters plants whenever the soil dries out.</p><img loading="lazy" height="2080" width="901" src="'+s+'" class="common_img" style="width:200px;"><h2 id="_13-2-technical-specifications" tabindex="-1">13.2 Technical Specifications <a class="header-anchor" href="#_13-2-technical-specifications" aria-label="Permalink to &quot;13.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Surface material</td><td style="text-align:center;">Immersion gold</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">66.0 × 23.4 × 10.6 mm</td></tr></tbody></table><h2 id="_13-3-hands-on-project" tabindex="-1">13.3 Hands-On Project <a class="header-anchor" href="#_13-3-hands-on-project" aria-label="Permalink to &quot;13.3 Hands-On Project&quot;">​</a></h2><h3 id="_13-3-1-project-overview" tabindex="-1">13.3.1 Project Overview <a class="header-anchor" href="#_13-3-1-project-overview" aria-label="Permalink to &quot;13.3.1 Project Overview&quot;">​</a></h3><p>This project uses the soil sensor to read analog moisture levels and print them to the serial port. Placing the probes into dry or damp soil shows how readings change in the serial monitor, demonstrating how the soil sensor detects moisture.</p><h3 id="_13-3-2-hardware-wiring" tabindex="-1">13.3.2 Hardware Wiring <a class="header-anchor" href="#_13-3-2-hardware-wiring" aria-label="Permalink to &quot;13.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the soil sensor to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="630" src="'+n+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_13-3-3-adding-extensions" tabindex="-1">13.3.3 Adding Extensions <a class="header-anchor" href="#_13-3-3-adding-extensions" aria-label="Permalink to &quot;13.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Soil sensor</strong> under the <strong>Sensor</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_13-3-4-complete-program-and-analysis" tabindex="-1">13.3.4 Complete Program and Analysis <a class="header-anchor" href="#_13-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;13.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, the analog moisture reading from the soil sensor on port P5 is continuously read.</p></li><li><p>The acquired reading is printed to the serial port.</p></li><li><p>A 0.5 s delay is added to slow down the refresh rate and stabilize serial readings.</p></li></ol><img loading="lazy" height="271" width="928" src="'+d+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/13 Soil Sensor.sb3</a>.</strong></p></div><h3 id="_13-3-5-program-upload" tabindex="-1">13.3.5 Program Upload <a class="header-anchor" href="#_13-3-5-program-upload" aria-label="Permalink to &quot;13.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+t+'" class="common_img" style="width:800px;"><h3 id="_13-3-6-implementation-outcome" tabindex="-1">13.3.6 Implementation Outcome <a class="header-anchor" href="#_13-3-6-implementation-outcome" aria-label="Permalink to &quot;13.3.6 Implementation Outcome&quot;">​</a></h3><p>Once the program upload is complete, observe the serial monitor in the lower-right corner of the programming software. When the sensor probes are in dry soil, the serial monitor displays lower values. Inserting the probes into damp soil raises the reading, with values ranging from 0 to 255.</p><img loading="lazy" height="905" width="1407" src="'+c+'" class="common_img" style="width:500px;">',26)])])}const w=o(h,[["render",p]]);export{x as __pageData,w as default};
